class SegNode {
  kids = new Map<string, SegNode>();
  constructor(public value: number) {}
}

class PathStore {
  private root = new SegNode(-1);

  create(path: string, value: number): boolean {
    const parts = path.split("/").slice(1);
    let node = this.root;
    for (let i = 0; i < parts.length - 1; i++) {
      const next = node.kids.get(parts[i]);
      if (!next) return false;
      node = next;
    }
    const last = parts[parts.length - 1];
    if (node.kids.has(last)) return false;
    node.kids.set(last, new SegNode(value));
    return true;
  }

  get(path: string): number {
    let node: SegNode | undefined = this.root;
    for (const part of path.split("/").slice(1)) {
      node = node.kids.get(part);
      if (!node) return -1;
    }
    return node.value;
  }
}

